"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { textRibbonPath, ribbonCopies, ribbonPeriod, advanceRibbonPhase, moveRibbonPhase, type TextRibbonShape } from "@/lib/cojeev/text-ribbon-path";
import { useGuidanceMotion } from "@/lib/cojeev-motion/use-guidance-motion";
import { assignMotionRef } from "@/lib/cojeev-motion/refs";

export type TextRibbonDirection = "forward" | "backward";

export type TextRibbonProps = Omit<React.ComponentProps<"div">, "children"> & {
  text: string;
  shape?: TextRibbonShape;
  /** Automatic movement is opt-in. Pair it with a visible pause control. */
  auto?: boolean;
  paused?: boolean;
  /** SVG units per second, bounded to 0–120. */
  speed?: number;
  /** Supply direction/onDirectionChange to control direction after dragging. */
  direction?: TextRibbonDirection;
  onDirectionChange?: (direction: TextRibbonDirection) => void;
  /** Wave and arch curvature, from a straight path (0) to the full curve (1). */
  curvature?: number;
  hoverBehavior?: "pause" | "slow" | "quicken" | "none";
  /** Horizontal drag, arrow keys and Home directly position the ribbon. */
  draggable?: boolean;
  /** Size in the 640 × 280 SVG, bounded to 24–56. The entire ribbon scales responsively. */
  fontSize?: number;
  separator?: string;
  guide?: boolean;
  tone?: "ink" | "pink" | "olive" | "blue" | "yellow";
};

/** A measured typographic path. Repeated glyphs are decorative; the actual phrase is read once. */
export function TextRibbon({ text, shape = "wave", auto = false, paused = false, speed = 28,
  direction, onDirectionChange, curvature = 1, hoverBehavior = "pause", draggable = false,
  fontSize = 40, separator = " · ", guide = true, tone = "ink",
  className, ref, onPointerEnter, onPointerLeave, onPointerDown, onPointerMove, onPointerUp, onPointerCancel,
  onLostPointerCapture, onKeyDown, onFocusCapture, onBlurCapture, style, ...props }: TextRibbonProps) {
  const host = React.useRef<HTMLDivElement>(null);
  const path = React.useRef<SVGPathElement>(null);
  const sample = React.useRef<SVGTextElement>(null);
  const textPath = React.useRef<SVGTextPathElement>(null);
  const phase = React.useRef(0);
  const velocity = React.useRef(0);
  const drag = React.useRef<{ id: number; x: number; y: number; distance: number; claimed: boolean } | null>(null);
  const [dragging, setDragging] = React.useState(false);
  const [localDirection, setLocalDirection] = React.useState<TextRibbonDirection>("forward");
  const [measure, setMeasure] = React.useState({ unit: 0, count: 1 });
  const [hovered, setHovered] = React.useState(false);
  const [focused, setFocused] = React.useState(false);
  const { quiet, enabled, inView } = useGuidanceMotion(host);
  const attach = React.useCallback((node: HTMLDivElement | null) => { host.current = node; return assignMotionRef(ref, node); }, [ref]);
  const id = `ribbon-${React.useId().replace(/:/g, "")}`;
  const size = Number.isFinite(fontSize) ? Math.min(56, Math.max(24, fontSize)) : 40;
  const pace = Number.isFinite(speed) ? Math.min(120, Math.max(0, speed)) : 28;
  const content = text.trim() ? text + separator : "";
  const heading = direction ?? localDirection;
  if (dragging && (!draggable || !inView)) setDragging(false);
  const running = auto && !paused && !(hovered && hoverBehavior === "pause") && !focused && !dragging && !quiet && enabled && inView && measure.unit > 0 && pace > 0;
  const targetSpeed = Math.min(120, pace * (hovered ? hoverBehavior === "slow" ? .25 : hoverBehavior === "quicken" ? 2 : 1 : 1)) * (heading === "forward" ? 1 : -1);
  const targetVelocity = React.useRef(targetSpeed);
  React.useEffect(() => { targetVelocity.current = targetSpeed; }, [targetSpeed]);
  const changeDirection = (next: TextRibbonDirection) => {
    if (direction === undefined) setLocalDirection(next);
    if (next !== heading) onDirectionChange?.(next);
  };
  const move = (distance: number) => {
    phase.current = moveRibbonPhase(phase.current, distance, measure.unit);
    textPath.current?.setAttribute("startOffset", String(-phase.current));
  };
  const finishDrag = (cancelled = false) => {
    const gesture = drag.current;
    drag.current = null;
    setDragging(false);
    if (!cancelled && gesture && Math.abs(gesture.distance) > 2) changeDirection(gesture.distance < 0 ? "forward" : "backward");
    if (gesture && host.current?.hasPointerCapture(gesture.id)) host.current.releasePointerCapture(gesture.id);
  };
  React.useEffect(() => {
    if (!draggable || !inView) {
      const gesture = drag.current;
      drag.current = null;
      if (gesture && host.current?.hasPointerCapture(gesture.id)) host.current.releasePointerCapture(gesture.id);
    }
  }, [draggable, inView]);
  React.useEffect(() => {
    const cancel = () => {
      const gesture = drag.current;
      drag.current = null; setDragging(false);
      if (gesture && host.current?.hasPointerCapture(gesture.id)) host.current.releasePointerCapture(gesture.id);
    };
    const visibility = () => { if (document.hidden) cancel(); };
    window.addEventListener("blur", cancel); document.addEventListener("visibilitychange", visibility);
    return () => { window.removeEventListener("blur", cancel); document.removeEventListener("visibilitychange", visibility); };
  }, []);

  React.useEffect(() => {
    const node = host.current;
    if (!node) return;
    let disposed = false;
    let frame = 0;
    const read = () => {
      frame = 0;
      if (disposed || !sample.current || !path.current) return;
      const natural = sample.current.getComputedTextLength();
      const length = path.current.getTotalLength();
      const unit = ribbonPeriod(length, natural, shape === "loop" || shape === "figure-eight" || shape === "circle");
      if (unit > 0 && length > 0) {
        phase.current = phase.current % unit;
        textPath.current?.setAttribute("startOffset", String(-phase.current));
      }
      const count = ribbonCopies(length, unit);
      setMeasure(old => old.unit === unit && old.count === count ? old : { unit, count });
    };
    const schedule = () => { if (!frame) frame = requestAnimationFrame(read); };
    read();
    const resize = new ResizeObserver(schedule);
    resize.observe(node);
    document.fonts.ready.then(() => { if (!disposed) schedule(); });
    document.fonts.addEventListener("loadingdone", schedule);
    return () => { disposed = true; if (frame) cancelAnimationFrame(frame); resize.disconnect(); document.fonts.removeEventListener("loadingdone", schedule); };
  }, [content, shape, size, curvature]);

  React.useEffect(() => {
    if (!running || !textPath.current) { velocity.current = 0; return; }
    let frame = 0;
    let previous: number | undefined;
    const tick = (now: number) => {
      const elapsed = previous === undefined ? 0 : (now - previous) / 1000;
      previous = now;
      velocity.current += (targetVelocity.current - velocity.current) * (1 - Math.exp(-Math.min(.05, elapsed) * 7));
      phase.current = advanceRibbonPhase(phase.current, elapsed, velocity.current, measure.unit);
      textPath.current?.setAttribute("startOffset", String(-phase.current));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [running, measure.unit]);

  return <div {...props} ref={attach}
    role={props.role ?? (draggable ? "group" : undefined)} tabIndex={props.tabIndex ?? (draggable ? 0 : undefined)}
    aria-label={props["aria-label"] ?? (draggable ? "Move text ribbon" : undefined)}
    aria-keyshortcuts={draggable ? "ArrowLeft ArrowRight Home" : undefined}
    data-slot="text-ribbon" data-shape={shape} data-tone={tone} data-running={running} data-draggable={draggable || undefined} data-dragging={dragging || undefined} data-direction={heading}
    className={cn("v-text-ribbon", className)} style={{ ...style, "--ribbon-size": `${size}px` } as React.CSSProperties}
    onPointerEnter={event => { onPointerEnter?.(event); if (!event.defaultPrevented && event.pointerType !== "touch") setHovered(true); }}
    onPointerLeave={event => { onPointerLeave?.(event); setHovered(false); }}
    onPointerDown={event => {
      onPointerDown?.(event);
      if (event.defaultPrevented || !draggable || !content || !event.isPrimary || event.button !== 0 || drag.current) return;
      drag.current = { id: event.pointerId, x: event.clientX, y: event.clientY, distance: 0, claimed: event.pointerType !== "touch" };
      event.currentTarget.setPointerCapture(event.pointerId); setDragging(true);
    }}
    onPointerMove={event => {
      onPointerMove?.(event);
      const gesture = drag.current;
      if (!gesture || gesture.id !== event.pointerId || event.defaultPrevented) return;
      const dx = event.clientX - gesture.x, dy = event.clientY - gesture.y;
      if (!gesture.claimed) {
        if (Math.abs(dy) > 6 && Math.abs(dy) > Math.abs(dx)) { finishDrag(true); return; }
        if (Math.abs(dx) < 6) return;
        gesture.claimed = true;
      }
      const units = shape === "circle" ? 280 : 640;
      move(-dx * units / Math.max(1, event.currentTarget.getBoundingClientRect().width));
      gesture.x = event.clientX; gesture.y = event.clientY; gesture.distance += dx;
    }}
    onPointerUp={event => { onPointerUp?.(event); if (drag.current?.id === event.pointerId) finishDrag(event.defaultPrevented); }}
    onPointerCancel={event => { onPointerCancel?.(event); finishDrag(true); }}
    onLostPointerCapture={event => { onLostPointerCapture?.(event); if (drag.current?.id === event.pointerId) finishDrag(true); }}
    onKeyDown={event => {
      onKeyDown?.(event);
      if (event.defaultPrevented || !draggable || event.target !== event.currentTarget || event.altKey || event.ctrlKey || event.metaKey) return;
      if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
        event.preventDefault(); const forward = event.key === "ArrowLeft";
        move(size * (event.shiftKey ? 2 : 1) * (forward ? 1 : -1)); changeDirection(forward ? "forward" : "backward");
      } else if (event.key === "Home") { event.preventDefault(); move(-phase.current); }
    }}
    onFocusCapture={event => { onFocusCapture?.(event); setFocused(true); }}
    onBlurCapture={event => { onBlurCapture?.(event); if (!(event.relatedTarget instanceof Node) || !event.currentTarget.contains(event.relatedTarget)) setFocused(false); }}>
    <span className="v-text-ribbon__accessible">{text}</span>
    <svg viewBox={shape === "circle" ? "180 0 280 280" : "0 0 640 280"} aria-hidden="true" focusable="false">
      <defs><path id={id} ref={path} d={textRibbonPath(shape, curvature)} /></defs>
      {guide && <use href={`#${id}`} className="v-text-ribbon__guide" />}
      <text ref={sample} className="v-text-ribbon__sample" xmlSpace="preserve">{content}</text>
      <text className="v-text-ribbon__words" xmlSpace="preserve" textLength={measure.unit > 0 ? measure.unit * measure.count : undefined} lengthAdjust="spacingAndGlyphs">
        <textPath ref={textPath} href={`#${id}`} startOffset="0">{content.repeat(measure.count)}</textPath>
      </text>
    </svg>
  </div>;
}

export type TextRibbonShape = "loop" | "circle" | "wave" | "arch" | "line" | "figure-eight";

/** Original paths in one 640 × 280 coordinate system, with room for glyph ascenders. */
export function textRibbonPath(shape: TextRibbonShape, curvature = 1) {
  const bend = Number.isFinite(curvature) ? Math.max(0, Math.min(1, curvature)) : 1;
  if (shape === "circle") return "M320 52A88 88 0 1 1 320 228A88 88 0 1 1 320 52Z";
  if (shape === "loop") return "M80 150C80 56 560 56 560 150C560 244 80 244 80 150Z";
  if (shape === "arch") return `M24 236C104 ${236 - 198 * bend} 536 ${236 - 198 * bend} 616 236`;
  if (shape === "line") return "M16 152H624";
  if (shape === "figure-eight") return "M320 146C390 54 564 52 564 146C564 240 390 238 320 146C250 54 76 52 76 146C76 240 250 238 320 146Z";
  return `M16 162C110 ${162 - 102 * bend} 212 ${162 - 94 * bend} 320 162S524 ${162 + 96 * bend} 624 ${162 - 20 * bend}`;
}

/** Direct manipulation uses the same wrapping as playback, in SVG coordinates. */
export function moveRibbonPhase(phase: number, distance: number, unitLength: number) {
  if (![phase, distance, unitLength].every(Number.isFinite) || unitLength <= 0) return 0;
  return (((phase + distance) % unitLength) + unitLength) % unitLength;
}

export function ribbonCopies(pathLength: number, unitLength: number) {
  if (!Number.isFinite(pathLength) || !Number.isFinite(unitLength) || pathLength <= 0 || unitLength <= 0) return 1;
  return Math.min(200, Math.max(2, Math.ceil(pathLength / unitLength) + 2));
}

/** Closed paths need a whole number of phrases, or their seam collides mid-word. */
export function ribbonPeriod(pathLength: number, measuredUnit: number, closed: boolean) {
  if (!closed || pathLength <= 0 || measuredUnit <= 0 || !Number.isFinite(pathLength + measuredUnit)) return measuredUnit;
  // A long phrase passes through at its natural scale; fitting the whole phrase
  // into a single lap would make editable/user-provided text unreadably narrow.
  if (measuredUnit > pathLength) return measuredUnit;
  return pathLength / Math.max(1, Math.round(pathLength / measuredUnit));
}

/** One phrase's phase; wrapping it never changes the visible repeated sequence. */
export function advanceRibbonPhase(phase: number, seconds: number, speed: number, unitLength: number) {
  if (![phase, seconds, speed, unitLength].every(Number.isFinite) || unitLength <= 0) return 0;
  const distance = phase + Math.max(0, Math.min(seconds, .05)) * speed;
  return moveRibbonPhase(0, distance, unitLength);
}

"use client";

import * as React from "react";
import { useChoreography } from "@/lib/cojeev-motion/choreography";
import { useMotionVisibility } from "@/lib/cojeev-motion/use-motion-visibility";

/** Decorative cues share the same global, local and visibility stillness boundary. */
export function useGuidanceMotion(ref: React.RefObject<HTMLElement | null>) {
  const { quiet } = useChoreography();
  const visibility = useMotionVisibility(ref);
  const subscribe = React.useCallback((listener: () => void) => {
    const observer = new MutationObserver(listener);
    for (let element = ref.current; element; element = element.parentElement) {
      observer.observe(element, { attributes: true, attributeFilter: ["data-flow", "data-no-glide"] });
    }
    return () => observer.disconnect();
  }, [ref]);
  const snapshot = React.useCallback(() => Boolean(ref.current?.closest('[data-flow="off"],[data-no-glide]')), [ref]);
  const localQuiet = React.useSyncExternalStore(subscribe, snapshot, () => false);
  return { ...visibility, quiet: quiet || localQuiet };
}

"use client";

import * as React from "react";
import { animate, frameSteps, motionValue, type AnimationPlaybackControls, type Transition } from "motion";
import { getMotionTime, isMotionClockFrozen, registerMotionClock } from "@/lib/cojeev-motion/clock";
import { getSettingsSnapshot, getServerSettingsSnapshot, subscribeSettings, type SettingsSnapshot } from "@/lib/cojeev-motion/settings";
import { useReducedMotion } from "@/lib/cojeev-motion/use-reduced-motion";

/** The shared rhythm. Durations and stagger are seconds, matching Motion's API. */
export const motionTokens = {
  spring: {
    responsive: { type: "spring", stiffness: 360, damping: 32, mass: .85 },
    expressive: { type: "spring", stiffness: 260, damping: 22, mass: 1 },
    gentle: { type: "spring", stiffness: 180, damping: 28, mass: 1 },
  },
  ease: { enter: [.2, .8, .2, 1], exit: [.4, 0, 1, 1], settle: [.2, .65, .25, 1] },
  duration: { quick: .16, enter: .32, exit: .18 },
  stagger: .035,
} as const;

export function resolveChoreography(snapshot: SettingsSnapshot, reduced: boolean): { quiet: boolean; transition: Transition } {
  const quiet = reduced || snapshot.motion.mode === "off" || snapshot.flow.variant === "off";
  if (quiet) return { quiet, transition: { duration: 0, delay: 0 } };
  const speed = snapshot.flow.speed;
  const spring = ["jelly", "rubber", "drop", "pebble"].includes(snapshot.flow.variant)
    ? motionTokens.spring.expressive : motionTokens.spring.responsive;
  return { quiet, transition: { ...spring, stiffness: spring.stiffness * speed * speed, damping: spring.damping * speed } };
}

/** Reactive settings subscription for reusable React surfaces. */
export function useChoreography() {
  const snapshot = React.useSyncExternalStore(subscribeSettings, getSettingsSnapshot, getServerSettingsSnapshot);
  const reduced = useReducedMotion();
  return React.useMemo(() => resolveChoreography(snapshot, reduced), [snapshot, reduced]);
}

/** Connect Motion's JS animations to the existing deterministic document clock. */
export function trackMotion(controls: AnimationPlaybackControls) {
  let origin = getMotionTime() - controls.time * 1000;
  let frozen = isMotionClockFrozen();
  if (frozen) controls.pause();
  const release = registerMotionClock(time => {
    if (time === null) {
      if (frozen) controls.play();
      frozen = false;
      return;
    }
    if (!frozen) {
      origin = time - controls.time * 1000;
      controls.pause();
      frozen = true;
    }
    controls.time = Math.max(0, time - origin) / 1000;
    if (controls.time >= controls.duration) controls.complete();
    // A seek schedules Motion's update phase. Flush it at this explicit sample;
    // normal playback stays entirely on Motion's own animation frame loop.
    frameSteps.update.process({ delta: 0, timestamp: performance.now(), isProcessing: false });
  });
  void controls.finished.then(release, release);
  return () => { release(); controls.stop(); };
}

/** One interruptible spring per scalar; retargets inherit the current value and velocity. */
export function createMotionLane(initial: number, render: (value: number) => void) {
  const value = motionValue(initial);
  const unsubscribe = value.on("change", render);
  let cancel = () => {};
  let generation = 0;
  const stop = () => { generation++; cancel(); cancel = () => {}; value.stop(); };
  const jump = (target: number) => { stop(); value.jump(target); render(target); };
  return {
    get: () => value.get(),
    jump,
    to(target: number, transition: Transition, complete?: () => void) {
      stop();
      if (transition.duration === 0) { jump(target); complete?.(); return; }
      const owner = generation;
      const controls = animate(value, target, {
        ...transition,
        autoplay: !isMotionClockFrozen(),
        onComplete: () => { if (generation === owner) complete?.(); },
      });
      cancel = trackMotion(controls);
    },
    stop,
    dispose: () => { stop(); unsubscribe(); value.destroy(); },
  };
}

/** One document-time clock for springs, cancellable phase timers, then Web Animations. */
export type MotionTimer = {at:number;run:()=>void;native:ReturnType<typeof setTimeout>|null;cancelled:boolean}
let time:number|null=null
const pending=new Set<MotionTimer>()
const drivers=new Set<(time:number|null)=>void>()
const animationStarts=new Map<Animation,{at:number;wasRunning:boolean}>()
const now=()=>time??performance.now()
function arm(timer:MotionTimer){timer.native=setTimeout(()=>{timer.native=null;if(timer.cancelled)return;pending.delete(timer);timer.run()},Math.max(0,timer.at-performance.now()))}
export function scheduleMotion(run:()=>void,delay:number):MotionTimer{
 const timer:MotionTimer={at:now()+Math.max(0,delay),run,native:null,cancelled:false};pending.add(timer)
 if(time===null)arm(timer)
 return timer
}
export function cancelMotion(timer:MotionTimer|null|undefined){if(!timer)return;timer.cancelled=true;if(timer.native!==null)clearTimeout(timer.native);timer.native=null;pending.delete(timer)}
export function registerMotionClock(driver:(time:number|null)=>void){drivers.add(driver);return ()=>{drivers.delete(driver)}}
export function getMotionTime(){return now()}
export function isMotionClockFrozen(){return time!==null}
/** Freeze before an interaction. First spring delta is zero; timer callbacks can enqueue subsequent beats. */
export function motionClock(next:number|null){
 if(next===null){
  const was=time;time=null
  if(was!==null)for(const timer of pending){timer.at=performance.now()+Math.max(0,timer.at-was);arm(timer)}
  drivers.forEach(driver=>driver(null))
  for(const [animation,state] of animationStarts){if(state.wasRunning)animation.play()}
  animationStarts.clear();return
 }
 if(!Number.isFinite(next))throw new Error("Motion clock expects finite milliseconds or null.")
 if(time===null){const real=performance.now();for(const timer of pending){if(timer.native!==null)clearTimeout(timer.native);timer.native=null;timer.at=next+Math.max(0,timer.at-real)}}
 time=next
 drivers.forEach(driver=>driver(next))
 // Due callbacks observe this clock sample, matching the source phase queue.
 let due:MotionTimer|undefined
 while((due=[...pending].filter(timer=>timer.at<=next).sort((a,b)=>a.at-b.at)[0])){
  pending.delete(due);if(due.cancelled)continue;due.run()
 }
 time=next
 if(typeof document!=="undefined"){
  const animations=document.getAnimations()
  for(const animation of animations){
   if(!animationStarts.has(animation)){animationStarts.set(animation,{at:next,wasRunning:animation.playState==="running"});animation.pause()}
   animation.currentTime=Math.max(0,next-animationStarts.get(animation)!.at)
  }
  for(const animation of animationStarts.keys())if(!animations.includes(animation))animationStarts.delete(animation)
 }
}
export const flowClock=motionClock

export const RUNTIME={cfg:{rest:false,reach:true,merge:true,hold:true,jiggleOn:true,press:true,echo:false,dots:0,grain:.08,sheen:.6,curve:1.2,lobeK:130,lobeZ:1,mergeZ:.8,arcK:40,holdK:80,pressK:170,jiggle:.35,jiggleDecay:1.6,restSpeed:1,drift:1,quality:2.5},
 tier:{pill:{amp:0,reach:3,inside:1.2,press:.02},tile:{amp:0,reach:2.4,inside:1,press:.02},nav:{amp:0,reach:1.2,inside:.5,press:.008},card:{amp:0,reach:1,inside:.4,press:.004},blob:{amp:.006,reach:3,inside:1.2,press:.03}}};
/* Per-tier authoring domains live with the profile, so a slider cannot offer a value the tier cannot mean
   (the spinner's amp .14 is legitimate and must not be clamped to the pill's 3 % ceiling). */
export const DOMAIN={amp:{max:{pill:3,tile:3,nav:1,card:1,blob:8,spinner:20},min:0},reach:{max:{pill:24,tile:24,nav:12,card:12,blob:32,spinner:0},min:0},inside:{max:{pill:12,tile:12,nav:6,card:6,blob:16,spinner:0},min:0},press:{max:{pill:12,tile:12,nav:4,card:4,blob:16,spinner:0},min:0},R:{max:{pill:240,tile:240,nav:160,card:160,blob:320,spinner:0},min:0},sig:{max:{pill:120,tile:120,nav:80,card:160,blob:160,spinner:8},min:1}};
export const factoryTiers={pill:{amp:.008,reach:4,inside:2,sig:24,R:80,press:.03,lobes:0,depth:0,asym:0,spread:.55},tile:{amp:.008,reach:3.5,inside:1.6,sig:18,R:64,press:.035,lobes:0,depth:0,asym:0,spread:.55},nav:{amp:.0006,reach:3,inside:1.2,sig:24,R:64,press:.010,lobes:0,depth:0,asym:0,spread:.55},card:{amp:.0003,reach:2.5,inside:.9,sig:44,R:56,press:.004,lobes:0,depth:0,asym:0,spread:.55},blob:{amp:.012,reach:4,inside:1.8,sig:22,R:64,press:.05,lobes:0,depth:0,asym:0,spread:.55},spinner:{amp:.14,reach:0,inside:0,sig:1,R:0,press:0,lobes:0,depth:0,asym:0,spread:.55}};
export const factoryCfg={quality:2.5,grain:.12,sheen:1,curve:1,lobeK:90,lobeZ:.9,mergeZ:.62,arcK:26,holdK:55,pressK:140,jiggle:.45,jiggleDecay:1.35,restSpeed:1,drift:1,rest:true,reach:true,merge:true,hold:true,jiggleOn:true,press:true,echo:false,echoOff:6,echoScale:1.04,dots:0};


export type MorphConfig = typeof factoryCfg
export type TierName = keyof typeof factoryTiers
export type Tier = typeof factoryTiers.pill
export type ProductCategory = "buttons" | "icons" | "pills" | "cards" | "skeleton"
export type Category = ProductCategory | "nav" | "inputs" | "controls" | "surfaces"
export type MotionSettings = {v:3;mode:"off"|"subtle";cats:Record<Category,boolean>}
export type MorphProfile = {cfg:MorphConfig;TIER:Record<TierName,Tier>}
export type FlowVariant = "glide"|"stretch"|"jelly"|"comet"|"drop"|"rubber"|"pebble"|"ripple"|"halo"|"off"
export type FlowSettings = {variant:FlowVariant;hover:boolean;speed:number;intensity:number;hoverStrength:number}
export type SettingsSnapshot = Readonly<{motion:MotionSettings;flow:FlowSettings;profile:MorphProfile;authored:boolean}>
export const MOTION_KEY = "v-motion"
export const MORPH_KEY = "v-morph-cfg-v3"
export const FLOW_KEY = "v-flow-v1"
export const PRODUCT_CATEGORIES:readonly ProductCategory[] = ["buttons","icons","pills","cards","skeleton"]
export const FLOW_DEFAULTS:Readonly<FlowSettings> = Object.freeze({variant:"glide",hover:true,speed:1,intensity:1,hoverStrength:1})
export const FLOW_CHARACTERS:Record<FlowVariant,{label:string;duration:number;ease:string;land:string;glow?:string}> = {
 glide:{label:"Glide",duration:.24,ease:"cubic-bezier(.2,.8,.2,1)",land:"none"},
 stretch:{label:"Stretch",duration:.3,ease:"cubic-bezier(.3,1.15,.4,1)",land:"vf-land"},
 jelly:{label:"Jelly",duration:.5,ease:"cubic-bezier(.3,1.3,.45,1)",land:"vf-jellyx"},
 comet:{label:"Comet",duration:.34,ease:"cubic-bezier(.2,.8,.2,1)",land:"vf-land"},
 drop:{label:"Ink drop",duration:.3,ease:"cubic-bezier(.3,1.25,.4,1)",land:"vf-bloom"},
 rubber:{label:"Rubber",duration:.36,ease:"cubic-bezier(.3,1.3,.4,1)",land:"vf-land"},
 pebble:{label:"Pebble",duration:.46,ease:"cubic-bezier(.32,1.25,.42,1)",land:"vf-lean"},
 ripple:{label:"Ripple",duration:.36,ease:"cubic-bezier(.2,.8,.2,1)",land:"vf-land",glow:"vf-ring"},
 halo:{label:"Halo",duration:.4,ease:"cubic-bezier(.3,1.2,.4,1)",land:"vf-land",glow:"vf-glow"},
